try {
    // POTÊNCIA TOTAL EM KW
    var potencia_total = {
        payload: parseFloat(msg.payload.pt)/1000,
    };

    // Tensões das três fases
    var tensao_fase_a = {
        payload: parseFloat(msg.payload.uarms),
    };

    var tensao_fase_b = {
        payload: parseFloat(msg.payload.ubrms),
    };

    var tensao_fase_c = {
        payload: parseFloat(msg.payload.ucrms),
    };

    // Correntes das três fases
    var corrente_fase_a = {
        payload: parseFloat(msg.payload.iarms),
    };

    var corrente_fase_b = {
        payload: parseFloat(msg.payload.ibrms),
    };

    var corrente_fase_c = {
        payload: parseFloat(msg.payload.icrms),
    };

    // FATOR DE POTÊNCIA
    var fator_de_potencia = {
        payload: parseFloat(msg.payload.pft),
    };

    // Energia 
    const energiaAtual = parseFloat(msg.payload.ept);

    // Array para armazenar amostras de energia (30 amostras = 15 minutos)
    var amostrasEnergia = context.get('amostrasEnergia') || [];

    // Adicionar nova amostra
    amostrasEnergia.push({
        energia: energiaAtual,
        timestamp: new Date()
    });

    // Manter apenas últimas 30 amostras (15 minutos)
    if (amostrasEnergia.length > 30) {
        amostrasEnergia = amostrasEnergia.slice(-30);
    }

    // Salvar array atualizado
    context.set('amostrasEnergia', amostrasEnergia);

    // Calcular demanda só quando tiver amostras suficientes
    var demandaAtual = 0;
    var demandaMaxima = context.get('demandaMaxima') || 0;

    if (amostrasEnergia.length >= 30) {
        // Pegar primeira e última amostra do período de 15 minutos
        const primeiraAmostra = amostrasEnergia[0];
        const ultimaAmostra = amostrasEnergia[amostrasEnergia.length - 1];

        // Calcular demanda
        const deltaEnergia = ultimaAmostra.energia - primeiraAmostra.energia;
        const deltaTempoHoras = 0.25; // 15 minutos = 0,25 horas

        demandaAtual = deltaEnergia / deltaTempoHoras;

        // Atualizar demanda máxima
        if (demandaAtual > demandaMaxima) {
            demandaMaxima = demandaAtual;
            context.set('demandaMaxima', demandaMaxima);
        }
    }

    var temperatura = {
        payload: parseFloat(msg.payload.tpsd),
   };

    // DEMANDA CALCULADA (MÉTODO DE AMOSTRAGEM)
    var demanda = {
        payload: parseFloat(demandaAtual.toFixed(2)),
        amostras: amostrasEnergia.length,
        timestamp: new Date().toISOString()
    };

    var demanda_maxima = {
        payload: parseFloat(demandaMaxima.toFixed(2)),
        timestamp: new Date().toISOString()
    };

    function calcularCustoMensal(potenciaKW) {
    const TARIFA_ENERGIA = 0.54; // R$/kWh

    // Recuperar acumulação atual
    var acumulacao = context.get('acumulacaoMensal') || {
        energiaTotal: 0,
        inicioMes: new Date()
    };

    // Verificar se mudou o mês
    const dataAtual = new Date();
    if (dataAtual.getMonth() !== acumulacao.inicioMes.getMonth()) {
        // Novo mês - reiniciar
        acumulacao = {
            energiaTotal: 0,
            inicioMes: dataAtual
        };
    }

    // Acumular energia (leitura a cada 30 segundos)
    const intervalo_de_leitura = 1 / 120; 
    acumulacao.energiaTotal += (potenciaKW * intervalo_de_leitura);

    // Salvar no contexto
    context.set('acumulacaoMensal', acumulacao);

    // Calcular custo
    let custoEnergia = acumulacao.energiaTotal * TARIFA_ENERGIA;

        return {
            energiaConsumida: acumulacao.energiaTotal,
            custoEnergia: custoEnergia,
            inicioMes: acumulacao.inicioMes
        };
    }

    // Uso
    const potenciaAtual = parseFloat(msg.payload.pt);
    const custos = calcularCustoMensal(potenciaAtual/1000);

    var custo_energia = {
        payload: parseFloat(custos.custoEnergia.toFixed(2)),
    };

    // VETORES PARA ARMAZENAR POTÊNCIAS DAS FASES

    // Vetor para potência da Fase A (W)
    var vetor_potencia_A = context.get('vetor_potencia_A') || [];
    vetor_potencia_A.push(parseFloat(msg.payload.pa || 0));
    if (vetor_potencia_A.length > 1000) vetor_potencia_A = vetor_potencia_A.slice(-500);
    context.set('vetor_potencia_A', vetor_potencia_A);

    // Vetor para potência da Fase B (W)
    var vetor_potencia_B = context.get('vetor_potencia_B') || [];
    vetor_potencia_B.push(parseFloat(msg.payload.pb || 0));
    if (vetor_potencia_B.length > 1000) vetor_potencia_B = vetor_potencia_B.slice(-500);
    context.set('vetor_potencia_B', vetor_potencia_B);

    // Vetor para potência da Fase C (W)
    var vetor_potencia_C = context.get('vetor_potencia_C') || [];
    vetor_potencia_C.push(parseFloat(msg.payload.pc || 0));
    if (vetor_potencia_C.length > 1000) vetor_potencia_C = vetor_potencia_C.slice(-500);
    context.set('vetor_potencia_C', vetor_potencia_C);

    // Vetor para potência Total (kW)
    var vetor_potencia_Total = context.get('vetor_potencia_Total') || [];
    vetor_potencia_Total.push(parseFloat(msg.payload.pt)/1000);
    if (vetor_potencia_Total.length > 1000) vetor_potencia_Total = vetor_potencia_Total.slice(-500);
    context.set('vetor_potencia_Total', vetor_potencia_Total);

    // Mensagens opcionais para monitorar os vetores
    var vetor_A = {
        payload: vetor_potencia_A,
        topic: "Vetor Potência Fase A",
        label: "Potência Fase A (W)",
        tamanho: vetor_potencia_A.length
    };

    var vetor_B = {
        payload: vetor_potencia_B,
        topic: "Vetor Potência Fase B", 
        label: "Potência Fase B (W)",
        tamanho: vetor_potencia_B.length
    };

    var vetor_C = {
        payload: vetor_potencia_C,
        topic: "Vetor Potência Fase C",
        label: "Potência Fase C (W)",
        tamanho: vetor_potencia_C.length
    };

    var vetor_Total = {
        payload: vetor_potencia_Total,
        topic: "Vetor Potência Total",
        label: "Potência Total (W)",
        tamanho: vetor_potencia_Total.length
    };

    // EXPORTAÇÃO PARA EXCEL COM ARQUIVO MENSAL
    var timestamp = new Date().toLocaleString('pt-BR');
    var dataHoje = new Date().toISOString().split('T')[0]; // YYYY-MM-DD
    var mesAtual = new Date().getMonth(); // 0-11
    var anoAtual = new Date().getFullYear();

    // Verificar se mudou o MÊS
    var ultimoMesRegistrado = context.get('ultimoMes');
    var isNovoMes = (ultimoMesRegistrado !== mesAtual);

    // Nome do arquivo MENSAL (YYYY-MM)
    var filename = `/data/dados_${anoAtual}-${String(mesAtual + 1).padStart(2, '0')}.xls`;

    // Verificar se é a primeira escrita no arquivo deste mês
    var arquivoAtual = context.get('arquivoAtual') || '';
    var isPrimeiraEscrita = (arquivoAtual !== filename);

    // Cabeçalho
    var header = "Data\tHora\tPotencia_Total_em_kW\tDemanda_Atual_em_kW\tDemanda_Maxima_em_kW\tFator_Potencia\tTensao_fase_A_em_Volts\tTensao_fase_B_em_Volts\tTensao_fase_C_em_Volts\tCorrente_Fase_A_em_Ampéres\tCorrente_Fase_B_em_Ampéres\tCorrente_Fase_C_em_Ampéres\tTemperatura_em_Graus_Celsius\tCusto_de_Energia_RS\n";

    // Dados
    var excelData = [
        `${timestamp.split(' ')[0]}\t`,
        `${timestamp.split(' ')[1]}\t`,
        `${(parseFloat(msg.payload.pt || 0)/1000).toFixed(3)}\t`,
        `${parseFloat(demandaAtual || 0).toFixed(3)}\t`,
        `${parseFloat(demandaMaxima || 0).toFixed(3)}\t`,
        `${parseFloat(msg.payload.pft || 0).toFixed(3)}\t`,
        `${parseFloat(msg.payload.uarms || 0).toFixed(2)}\t`,
        `${parseFloat(msg.payload.ubrms || 0).toFixed(2)}\t`,
        `${parseFloat(msg.payload.ucrms || 0).toFixed(2)}\t`,
        `${parseFloat(msg.payload.iarms || 0).toFixed(3)}\t`,
        `${parseFloat(msg.payload.ibrms || 0).toFixed(3)}\t`,
        `${parseFloat(msg.payload.icrms || 0).toFixed(3)}\t`,
        `${parseFloat(msg.payload.tpsd || 0).toFixed(2)}\t`,
        `${parseFloat(custos?.custoEnergia || 0).toFixed(2)}`
    ].join('');

    // Se for novo mês OU primeira escrita no arquivo, adiciona header
    var payloadExcel = '';
    if (isNovoMes || isPrimeiraEscrita) {
        payloadExcel = header + excelData;
        // Atualizar controle do arquivo atual
        context.set('arquivoAtual', filename);
    } else {
        payloadExcel = excelData;
    }

    var msg_excel = {
        payload: payloadExcel,
        topic: "excel_data",
        filename: filename
    };

    // Atualizar último mês registrado
    if (isNovoMes) {
        context.set('ultimoMes', mesAtual);
        // Limpar demanda máxima no novo mês (opcional)
        context.set('demandaMaxima', 0);
    }

    var msg_timestamp = {
        payload: timestamp,  
        topic: "timestamp",
        formatted: new Date().toLocaleString('pt-BR'),
        unix: Date.now()
    };

    // Retornar todas as mensagens 
    return [
        potencia_total, tensao_fase_a, tensao_fase_b, tensao_fase_c, corrente_fase_a, corrente_fase_b, corrente_fase_c,
        fator_de_potencia, temperatura, demanda, demanda_maxima,
        custo_energia, vetor_A, vetor_B, vetor_C, vetor_Total, msg_excel, msg_timestamp,
    ];

} catch (error) {
    node.error("Erro ao processar dados: " + error.message);
    return null;
}

